import 'package:flutter/widgets.dart';
import '../services/archive_viewer_service.dart';

/// Formats only known app-authored archive errors; unknown details pass through.
String localizedArchiveViewerError(BuildContext context, Object error) {
  final ArchiveMessageCode? code;
  final Map<String, Object> arguments;
  if (error is ArchiveViewException) { code = error.code; arguments = error.arguments; }
  else if (error is ArchivePasswordRequiredException) { code = error.code; arguments = error.arguments; }
  else { return error.toString(); }
  if (code == null) return error.toString();
  final language = Localizations.maybeLocaleOf(context)?.languageCode ?? 'en';
  final template = (_messages[language] ?? _messages['en']!)[code.name];
  if (template == null) return error.toString();
  return template.replaceAllMapped(RegExp(r'\{([A-Za-z]+)\}'), (match) {
    final value = arguments[match.group(1)];
    return value == null ? match.group(0)! : value.toString();
  });
}

